remediation.command:
$ErrorActionPreference = 'Stop'
$tmaBk = Join-Path $env:ProgramData 'TMAegis\backup'
function Backup-TmaKey([string]$p) {
  try {
    if (Test-Path -LiteralPath $p) {
      $k = $p -replace '^Registry::', ''
      New-Item -ItemType Directory -Force -Path $tmaBk | Out-Null
      $f = Join-Path $tmaBk (($k -replace '[\\/:*?"<>|]', '_') + '.reg')
      if (-not (Test-Path -LiteralPath $f)) { & reg.exe export $k $f | Out-Null }
    }
  } catch { }
}
function Set-TmaReg([string]$p, [string]$n, $v, [string]$t) {
  Backup-TmaKey $p
  if (-not (Test-Path -LiteralPath $p)) { New-Item -Path $p -Force | Out-Null }
  New-ItemProperty -LiteralPath $p -Name $n -Value $v -PropertyType $t -Force | Out-Null
}
function Remove-TmaValue([string]$p, [string]$n) {
  if ((Test-Path -LiteralPath $p) -and ($null -ne (Get-ItemProperty -LiteralPath $p -Name $n -ErrorAction SilentlyContinue))) {
    Backup-TmaKey $p
    Remove-ItemProperty -LiteralPath $p -Name $n -Force
  }
}
function Remove-TmaKey([string]$p) {
  if (Test-Path -LiteralPath $p) { Backup-TmaKey $p; Remove-Item -LiteralPath $p -Recurse -Force }
}
function Set-TmaList([string]$p, [string[]]$items, [bool]$replace) {
  Backup-TmaKey $p
  if ($replace) { Remove-TmaKey $p }
  if (-not (Test-Path -LiteralPath $p)) { New-Item -Path $p -Force | Out-Null }
  $have = @((Get-ItemProperty -LiteralPath $p -ErrorAction SilentlyContinue).PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' } | ForEach-Object { "$($_.Value)" })
  $n = [int](@((Get-Item -LiteralPath $p).GetValueNames()) | ForEach-Object { $x = 0; if ([int]::TryParse($_, [ref]$x)) { $x } else { 0 } } | Measure-Object -Maximum).Maximum
  foreach ($i in $items) {
    if ($have -notcontains $i) { $n++; New-ItemProperty -LiteralPath $p -Name "$n" -Value $i -PropertyType String -Force | Out-Null }
  }
}
Remove-TmaKey 'Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Policies\Mozilla\Firefox\Authentication\NTLM'
